-- CasaPilot V69 Professionisti Plus. Eseguire solo dopo backup del database.
create extension if not exists "pgcrypto";
create table if not exists public.professional_categories(id text primary key,name text not null,description text not null default '',availability_status text not null default 'limited' check(availability_status in('active','limited','activating')),sort_order integer not null default 0,is_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.professional_service_catalog(id text primary key,category_id text not null references public.professional_categories(id) on delete cascade,name text not null,description text not null default '',availability_status text not null default 'limited' check(availability_status in('active','limited','activating')),eligible_professions jsonb not null default '[]'::jsonb,wizard_config jsonb not null default '{}'::jsonb,quote_config jsonb not null default '{}'::jsonb,review_config jsonb not null default '{}'::jsonb,is_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.professional_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,account_type text not null,display_name text not null,profession text not null,bio text not null default '',years_experience integer not null default 0,online_available boolean not null default false,verification_status text not null default 'incomplete' check(verification_status in('incomplete','pending','verified','update_required','suspended')),average_rating numeric(3,2) not null default 0,verified_reviews_count integer not null default 0,average_response_minutes integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.professional_profile_services(professional_id uuid not null references public.professional_profiles(id) on delete cascade,service_id text not null references public.professional_service_catalog(id) on delete cascade,pricing_mode text,price_min numeric(12,2),price_max numeric(12,2),is_active boolean not null default true,primary key(professional_id,service_id));
create table if not exists public.professional_service_areas(id uuid primary key default gen_random_uuid(),professional_id uuid not null references public.professional_profiles(id) on delete cascade,service_id text references public.professional_service_catalog(id) on delete cascade,country_code text not null default 'IT',region text,province text,municipality text,radius_km integer,online_only boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.professional_verifications(id uuid primary key default gen_random_uuid(),professional_id uuid not null references public.professional_profiles(id) on delete cascade,verification_type text not null,status text not null default 'pending' check(status in('pending','verified','rejected','expired')),document_path text,verified_by uuid references auth.users(id),verified_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.lead_requests(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,property_id uuid,category_id text not null references public.professional_categories(id),service_id text not null references public.professional_service_catalog(id),property_label text not null,approximate_location text not null,exact_address jsonb,answers jsonb not null default '{}'::jsonb,urgency text,budget_min numeric(12,2),budget_max numeric(12,2),notes text not null default '',lead_score smallint not null default 0 check(lead_score between 0 and 100),status text not null default 'draft' check(status in('draft','submitted','matching','matched','viewed','quote_received','quote_accepted','contacts_unlocked','job_in_progress','job_completed','cancelled')),max_matches integer not null default 3 check(max_matches between 1 and 5),submitted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.lead_matches(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.lead_requests(id) on delete cascade,professional_id uuid not null references public.professional_profiles(id) on delete cascade,match_score numeric(5,2),status text not null default 'invited' check(status in('invited','viewed','declined','quoting','quoted','expired')),decline_reason text,invited_at timestamptz not null default now(),viewed_at timestamptz,responded_at timestamptz,unique(lead_id,professional_id));
create table if not exists public.quotes(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.lead_requests(id) on delete cascade,professional_id uuid not null references public.professional_profiles(id) on delete cascade,price_type text not null,price_min numeric(12,2) not null,price_max numeric(12,2),vat_included boolean not null default true,included_items jsonb not null default '[]'::jsonb,excluded_items jsonb not null default '[]'::jsonb,additional_costs text not null default '',first_availability text,estimated_duration text,valid_until timestamptz,message text not null default '',status text not null default 'draft' check(status in('draft','sent','viewed','accepted','rejected','withdrawn')),sent_at timestamptz,viewed_at timestamptz,accepted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.lead_requests(id) on delete cascade,professional_id uuid not null references public.professional_profiles(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,contacts_unlocked boolean not null default false,created_at timestamptz not null default now(),unique(lead_id,professional_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id),body text not null,filtered_contact_data boolean not null default false,attachment_paths jsonb not null default '[]'::jsonb,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.contact_unlocks(id uuid primary key default gen_random_uuid(),lead_id uuid not null unique references public.lead_requests(id) on delete cascade,quote_id uuid not null unique references public.quotes(id) on delete cascade,owner_id uuid not null references auth.users(id),professional_id uuid not null references public.professional_profiles(id),unlocked_at timestamptz not null default now());
create table if not exists public.professional_jobs(id uuid primary key default gen_random_uuid(),lead_id uuid not null unique references public.lead_requests(id) on delete cascade,quote_id uuid not null unique references public.quotes(id) on delete cascade,owner_id uuid not null references auth.users(id),professional_id uuid not null references public.professional_profiles(id),status text not null default 'pending' check(status in('pending','appointment_scheduled','waiting_documents','in_progress','waiting_owner','completed','issue_reported','cancelled')),started_at timestamptz,completed_at timestamptz,updated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.professional_reviews(id uuid primary key default gen_random_uuid(),job_id uuid not null unique references public.professional_jobs(id) on delete cascade,lead_id uuid not null references public.lead_requests(id),owner_id uuid not null references auth.users(id),professional_id uuid not null references public.professional_profiles(id),clarity smallint not null check(clarity between 1 and 5),communication smallint not null check(communication between 1 and 5),punctuality smallint not null check(punctuality between 1 and 5),quality smallint not null check(quality between 1 and 5),value smallint not null check(value between 1 and 5),comment text not null default '',professional_reply text,is_verified boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.lead_events(id bigint generated always as identity primary key,lead_id uuid not null references public.lead_requests(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());

create or replace function public.accept_professional_quote(p_quote_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare v_quote public.quotes; v_lead public.lead_requests;
begin
  select * into v_quote from public.quotes where id=p_quote_id for update;
  if v_quote.id is null then raise exception 'Quote not found'; end if;
  select * into v_lead from public.lead_requests where id=v_quote.lead_id for update;
  if v_lead.owner_id<>auth.uid() then raise exception 'Not authorized'; end if;
  update public.quotes set status=case when id=p_quote_id then 'accepted' else 'rejected' end,accepted_at=case when id=p_quote_id then now() else accepted_at end where lead_id=v_quote.lead_id and status in('sent','viewed','accepted');
  update public.lead_requests set status='contacts_unlocked',updated_at=now() where id=v_quote.lead_id;
end; $$;

alter table public.professional_categories enable row level security; alter table public.professional_service_catalog enable row level security; alter table public.professional_profiles enable row level security; alter table public.professional_profile_services enable row level security; alter table public.professional_service_areas enable row level security; alter table public.professional_verifications enable row level security; alter table public.lead_requests enable row level security; alter table public.lead_matches enable row level security; alter table public.quotes enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.contact_unlocks enable row level security; alter table public.professional_jobs enable row level security; alter table public.professional_reviews enable row level security; alter table public.lead_events enable row level security;
drop policy if exists catalog_read on public.professional_categories; create policy catalog_read on public.professional_categories for select to authenticated using(is_enabled=true);
drop policy if exists services_read on public.professional_service_catalog; create policy services_read on public.professional_service_catalog for select to authenticated using(is_enabled=true);
drop policy if exists lead_owner_all on public.lead_requests; create policy lead_owner_all on public.lead_requests for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists lead_matched_read on public.lead_requests; create policy lead_matched_read on public.lead_requests for select to authenticated using(exists(select 1 from public.lead_matches lm join public.professional_profiles pp on pp.id=lm.professional_id where lm.lead_id=lead_requests.id and pp.user_id=auth.uid()));
drop policy if exists quote_owner_read on public.quotes; create policy quote_owner_read on public.quotes for select to authenticated using(exists(select 1 from public.lead_requests lr where lr.id=quotes.lead_id and lr.owner_id=auth.uid()));
drop policy if exists quote_professional_all on public.quotes; create policy quote_professional_all on public.quotes for all to authenticated using(exists(select 1 from public.professional_profiles pp where pp.id=quotes.professional_id and pp.user_id=auth.uid())) with check(exists(select 1 from public.professional_profiles pp where pp.id=quotes.professional_id and pp.user_id=auth.uid()));
drop policy if exists reviews_read on public.professional_reviews; create policy reviews_read on public.professional_reviews for select to authenticated using(is_verified=true);
